define class Scores extends Map<String, int> as
    pub bonus(): int { return 40 + self.size(); }
end
pub fnc main(): int {
    const Scores s = {"alice": 95, "bob": 80};
    return s.bonus();
}

define class StringMap<V> extends Map<String, V> as
    pub count(): int { return self.size(); }
end
define class Scores extends StringMap<int> as
    pub bonus(): int { return self.count() + 40; }
end
pub fnc main(): int {
    const Scores s = {"alice": 95, "bob": 80};
    return s.bonus();
}

define record Person extends Record as
    int age;
    pub years(): int { return self.age; }
end
pub fnc main(): int {
    const Person p = (age = 42);
    return p.years();
}

define record Person extends Record as
    int age;
    pub years(): int { return self.age; }
end
define record Employee extends Person as
    int salary;
    pub annual_salary(): int { return self.salary * 12; }
end
pub fnc main(): int {
    const Employee e = (age = 18, salary = 2);
    return e.years() + e.annual_salary();
}

